1	package server
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"io"
7		"net/http"
8		"net/url"
9		"sort"
10		"strconv"
11		"strings"
12		"unicode"
13		"unicode/utf8"
14	)
15	
16	// metaPrefix is the header prefix carrying user metadata on object writes.
17	// The constant is already in Go's canonical header form.
18	const metaPrefix = "X-Vaultgrid-Meta-"
19	
20	type createBucketInput struct {
21		ID     string `json:"id"`
22		PoolID string `json:"poolId"`
23	}
24	
25	// bucketView is the public representation of a bucket.
26	type bucketView struct {
27		ID          string `json:"id"`
28		PoolID      string `json:"poolId"`
29		ObjectCount int    `json:"objectCount"`
30		BytesUsed   int64  `json:"bytesUsed"`
31	}
32	
33	// objectView is the public representation of an object after a write, and
34	// the summary shape used in object listings.
35	type objectView struct {
36		Key       string            `json:"key"`
37		SizeBytes int64             `json:"sizeBytes"`
38		Metadata  map[string]string `json:"metadata"`
39		ETag      string            `json:"etag"`
40	}
41	
42	// bucket is a namespace of objects bound to one pool. bytesUsed is kept in
43	// sync with the sum of its objects' sizes; the same total is charged to the
44	// pool as objectBytes.
45	type bucket struct {
46		id      string
47		poolID  string
48		objects map[string]*object
49	}
50	
51	func (b *bucket) bytesUsed() int64 {
52		var total int64
53		for _, o := range b.objects {
54			total += o.sizeBytes
55		}
56		return total
57	}
58	
59	func (b *bucket) view() bucketView {
60		return bucketView{ID: b.id, PoolID: b.poolID, ObjectCount: len(b.objects), BytesUsed: b.bytesUsed()}
61	}
62	
63	// object is a stored byte sequence with user metadata. etag is the quoted
64	// lowercase hex SHA-256 of content.
65	type object struct {
66		key       string
67		content   []byte
68		metadata  map[string]string
69		etag      string
70		sizeBytes int64
71	}
72	
73	func (o *object) view() objectView {
74		return objectView{Key: o.key, SizeBytes: o.sizeBytes, Metadata: o.metadata, ETag: o.etag}
75	}
76	
77	// routeBuckets dispatches /v1/buckets and its sub-paths. The object key is
78	// the remainder of the path after "objects/" (already URL-decoded once by
79	// the net/http layer) and may contain slashes, so it is not split here.
80	func (s *store) routeBuckets(w http.ResponseWriter, r *http.Request) {
81		rest := strings.TrimPrefix(r.URL.Path, bucketPath)
82		if rest == "" {
83			switch r.Method {
84			case http.MethodGet:
85				s.listBuckets(w)
86			case http.MethodPost:
87				s.createBucket(w, r)
88			default:
89				methodNotAllowed(w, http.MethodGet, http.MethodPost)
90			}
91			return
92		}
93		// rest begins with "/"; the bucket id is the single next segment.
94		bucketID, tail, found := strings.Cut(rest[1:], "/")
95		if bucketID == "" {
96			writeError(w, http.StatusNotFound, "not_found")
97			return
98		}
99		if !found {
100			switch r.Method {
101			case http.MethodGet:
102				s.getBucket(w, bucketID)
103			case http.MethodDelete:
104				s.deleteBucket(w, bucketID)
105			default:
106				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
107			}
108			return
109		}
110		if tail == "objects" {
111			if r.Method != http.MethodGet {
112				methodNotAllowed(w, http.MethodGet)
113				return
114			}
115			s.listObjects(w, r, bucketID)
116			return
117		}
118		if key, ok := strings.CutPrefix(tail, "objects/"); ok {
119			switch r.Method {
120			case http.MethodPut:
121				s.putObject(w, r, bucketID, key)
122			case http.MethodGet:
123				s.getObject(w, r, bucketID, key, false)
124			case http.MethodHead:
125				s.getObject(w, r, bucketID, key, true)
126			case http.MethodDelete:
127				s.deleteObject(w, r, bucketID, key)
128			default:
129				methodNotAllowed(w, http.MethodPut, http.MethodGet, http.MethodHead, http.MethodDelete)
130			}
131			return
132		}
133		writeError(w, http.StatusNotFound, "not_found")
134	}
135	
136	func (s *store) listBuckets(w http.ResponseWriter) {
137		s.mu.RLock()
138		ids := make([]string, 0, len(s.buckets))
139		for id := range s.buckets {
140			ids = append(ids, id)
141		}
142		sort.Strings(ids)
143		items := make([]bucketView, 0, len(ids))
144		for _, id := range ids {
145			items = append(items, s.buckets[id].view())
146		}
147		s.mu.RUnlock()
148		writeJSON(w, http.StatusOK, map[string]any{"items": items})
149	}
150	
151	func (s *store) getBucket(w http.ResponseWriter, id string) {
152		if !validID(id) {
153			writeError(w, http.StatusBadRequest, "invalid_request")
154			return
155		}
156		s.mu.RLock()
157		b, ok := s.buckets[id]
158		var v bucketView
159		if ok {
160			v = b.view()
161		}
162		s.mu.RUnlock()
163		if !ok {
164			writeError(w, http.StatusNotFound, "bucket_not_found")
165			return
166		}
167		writeJSON(w, http.StatusOK, v)
168	}
169	
170	func (s *store) createBucket(w http.ResponseWriter, r *http.Request) {
171		var in createBucketInput
172		if !decodeRequest(r, &in) {
173			writeError(w, http.StatusBadRequest, "invalid_request")
174			return
175		}
176		if !validID(in.ID) || !validID(in.PoolID) {
177			writeError(w, http.StatusBadRequest, "invalid_request")
178			return
179		}
180	
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		if existing, dup := s.buckets[in.ID]; dup {
184			if existing.poolID == in.PoolID {
185				writeJSON(w, http.StatusOK, existing.view())
186				return
187			}
188			writeError(w, http.StatusConflict, "bucket_exists")
189			return
190		}
191		if _, ok := s.pools[in.PoolID]; !ok {
192			writeError(w, http.StatusNotFound, "pool_not_found")
193			return
194		}
195		s.buckets[in.ID] = &bucket{id: in.ID, poolID: in.PoolID, objects: make(map[string]*object)}
196		writeJSON(w, http.StatusCreated, s.buckets[in.ID].view())
197	}
198	
199	func (s *store) deleteBucket(w http.ResponseWriter, id string) {
200		if !validID(id) {
201			writeError(w, http.StatusBadRequest, "invalid_request")
202			return
203		}
204		s.mu.Lock()
205		defer s.mu.Unlock()
206		b, ok := s.buckets[id]
207		if !ok {
208			writeError(w, http.StatusNotFound, "bucket_not_found")
209			return
210		}
211		if len(b.objects) > 0 {
212			writeError(w, http.StatusConflict, "bucket_not_empty")
213			return
214		}
215		delete(s.buckets, id)
216		w.WriteHeader(http.StatusNoContent)
217	}
218	
219	// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
220	// control characters.
221	func validObjectKey(key string) bool {
222		if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
223			return false
224		}
225		for _, r := range key {
226			if unicode.IsControl(r) {
227				return false
228			}
229		}
230		return true
231	}
232	
233	// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
234	// metadata map keyed by the suffix after the prefix. A header with an empty
235	// suffix or a value that is not valid UTF-8 or carries control characters
236	// makes the whole request invalid.
237	func extractMetadata(h http.Header) (map[string]string, bool) {
238		meta := make(map[string]string)
239		for name, values := range h {
240			suffix, ok := strings.CutPrefix(name, metaPrefix)
241			if !ok {
242				continue
243			}
244			if suffix == "" {
245				return nil, false
246			}
247			for _, v := range values {
248				if !utf8.ValidString(v) {
249					return nil, false
250				}
251				for _, r := range v {
252					if unicode.IsControl(r) {
253						return nil, false
254					}
255				}
256			}
257			meta[suffix] = strings.Join(values, ", ")
258		}
259		return meta, true
260	}
261	
262	// parsePrecondition validates the conditional-write headers. It returns the
263	// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
264	// is false when both headers are present or either has an unsupported form.
265	func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
266		matches, hasMatch := h["If-Match"]
267		noneMatches, hasNoneMatch := h["If-None-Match"]
268		if hasMatch && hasNoneMatch {
269			return "", false, false
270		}
271		if hasMatch {
272			if len(matches) != 1 || !isQuotedETag(matches[0]) {
273				return "", false, false
274			}
275			return matches[0], false, true
276		}
277		if hasNoneMatch {
278			if len(noneMatches) != 1 || noneMatches[0] != "*" {
279				return "", false, false
280			}
281			return "", true, true
282		}
283		return "", false, true
284	}
285	
286	// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
287	// "9f86d081...". The content is not checked against any object here.
288	func isQuotedETag(v string) bool {
289		if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
290			return false
291		}
292		inner := v[1 : len(v)-1]
293		if inner == "" {
294			return false
295		}
296		for _, c := range inner {
297			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
298				return false
299			}
300		}
301		return true
302	}
303	
304	func etagOf(content []byte) string {
305		sum := sha256.Sum256(content)
306		return `"` + hex.EncodeToString(sum[:]) + `"`
307	}
308	
309	func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
310		if !validID(bucketID) || !validObjectKey(key) {
311			writeError(w, http.StatusBadRequest, "invalid_request")
312			return
313		}
314		if r.URL.RawQuery != "" {
315			writeError(w, http.StatusBadRequest, "invalid_request")
316			return
317		}
318		metadata, ok := extractMetadata(r.Header)
319		if !ok {
320			writeError(w, http.StatusBadRequest, "invalid_request")
321			return
322		}
323		ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
324		if !ok {
325			writeError(w, http.StatusBadRequest, "invalid_request")
326			return
327		}
328		content, err := io.ReadAll(r.Body)
329		if err != nil {
330			writeError(w, http.StatusBadRequest, "invalid_request")
331			return
332		}
333		etag := etagOf(content)
334		size := int64(len(content))
335	
336		s.mu.Lock()
337		defer s.mu.Unlock()
338		b, ok := s.buckets[bucketID]
339		if !ok {
340			writeError(w, http.StatusNotFound, "bucket_not_found")
341			return
342		}
343		existing := b.objects[key]
344		if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
345			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
346			return
347		}
348		if ifNoneMatchStar && existing != nil {
349			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
350			return
351		}
352		var oldSize int64
353		if existing != nil {
354			oldSize = existing.sizeBytes
355		}
356		p := s.pools[b.poolID]
357		// The store lock makes the capacity check and the charge atomic, so
358		// concurrent writes can never overcommit the pool, and a failed write
359		// leaves the old object and its metadata untouched.
360		if p.allocated() > p.rawCapacity-(size-oldSize) {
361			writeError(w, http.StatusConflict, "insufficient_capacity")
362			return
363		}
364		b.objects[key] = &object{key: key, content: content, metadata: metadata, etag: etag, sizeBytes: size}
365		p.objectBytes += size - oldSize
366		status := http.StatusCreated
367		if existing != nil {
368			status = http.StatusOK
369		}
370		w.Header().Set("ETag", etag)
371		writeJSON(w, status, b.objects[key].view())
372	}
373	
374	// getObject serves both GET and HEAD; headOnly suppresses the body.
375	func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
376		if !validID(bucketID) || !validObjectKey(key) {
377			writeError(w, http.StatusBadRequest, "invalid_request")
378			return
379		}
380		if r.URL.RawQuery != "" {
381			writeError(w, http.StatusBadRequest, "invalid_request")
382			return
383		}
384		s.mu.RLock()
385		b, ok := s.buckets[bucketID]
386		var o *object
387		if ok {
388			o = b.objects[key]
389		}
390		s.mu.RUnlock()
391		if !ok {
392			writeError(w, http.StatusNotFound, "bucket_not_found")
393			return
394		}
395		if o == nil {
396			writeError(w, http.StatusNotFound, "object_not_found")
397			return
398		}
399		for name, value := range o.metadata {
400			w.Header().Set(metaPrefix+name, value)
401		}
402		w.Header().Set("ETag", o.etag)
403		w.Header().Set("Content-Type", "application/octet-stream")
404		w.Header().Set("Content-Length", strconv.FormatInt(o.sizeBytes, 10))
405		w.WriteHeader(http.StatusOK)
406		if !headOnly {
407			_, _ = w.Write(o.content)
408		}
409	}
410	
411	func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
412		if !validID(bucketID) || !validObjectKey(key) {
413			writeError(w, http.StatusBadRequest, "invalid_request")
414			return
415		}
416		if r.URL.RawQuery != "" {
417			writeError(w, http.StatusBadRequest, "invalid_request")
418			return
419		}
420		s.mu.Lock()
421		defer s.mu.Unlock()
422		b, ok := s.buckets[bucketID]
423		if !ok {
424			writeError(w, http.StatusNotFound, "bucket_not_found")
425			return
426		}
427		// Deleting an unknown or already-deleted object is a success.
428		if o, exists := b.objects[key]; exists {
